INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('seviye-testi', 'Elif''in Yeni Komşusu', 'Elif, dokuz yaşında neşeli bir kızdı. Annesi ve küçük kardeşi Can ile birlikte mavi bir apartmanda oturuyordu. Bir cumartesi sabahı, kapının önünde büyük kutular gördü. Karşı daireye yeni bir aile taşınıyordu.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karşı daireye kim taşınıyordu?', 'Elif''in teyzesi', 'Yeni bir aile', 'Bir öğretmen', 'Yaşlı bir adam', 'b', 'Metinde karşı daireye yeni bir ailenin taşındığı söyleniyor.' FROM texts WHERE slug = 'seviye-testi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Zeynep elinde ne taşıyordu?', 'Bir kedi', 'Bir kitap', 'Bir saksı', 'Bir top', 'c', 'Zeynep, içinde sarı bir çiçek olan saksıyı dikkatle taşıyordu.' FROM texts WHERE slug = 'seviye-testi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Zeynep neden biraz üzgündü?', 'Burada hiç kimseyi tanımıyordu', 'Oyuncağı kırılmıştı', 'Çiçeği solmuştu', 'Kutular çok ağırdı', 'a', 'Zeynep başka bir şehirden gelmişti ve burada kimseyi tanımıyordu.' FROM texts WHERE slug = 'seviye-testi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Elif''in annesi yeni komşular için ne yaptı?', 'Çorba pişirdi', 'Çiçek aldı', 'Pasta satın aldı', 'Kurabiye pişirdi', 'd', 'Elif''in annesi bir tepsi kurabiye pişirdi, çocuklar da onları komşulara götürdü.' FROM texts WHERE slug = 'seviye-testi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Taşınmak çok yorucudur.', 'Yeni gelenlere yardım etmek güzel dostluklar kurar.', 'Çiçekler her gün sulanmalıdır.', 'Kardeşler hep oyun oynar.', 'b', 'Elif, yeni komşusuna yardım ederek yeni bir arkadaş kazandı.' FROM texts WHERE slug = 'seviye-testi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('minik-kedi-pamuk', 'Minik Kedi Pamuk', 'Ayşe''nin beyaz bir kedisi var. Kedinin adı Pamuk. Pamuk çok küçük ve çok tatlı. Tüyleri yumuşacık, gözleri yeşil.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pamuk''un gözleri ne renktir?', 'Mavi', 'Kahverengi', 'Yeşil', 'Sarı', 'c', 'Metinde Pamuk''un gözlerinin yeşil olduğu yazıyor.' FROM texts WHERE slug = 'minik-kedi-pamuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pamuk''un en sevdiği oyuncak hangisidir?', 'Kırmızı bir yün yumağı', 'Küçük bir top', 'Bir tüy', 'Bir fare oyuncağı', 'a', 'Pamuk''un en sevdiği oyuncak kırmızı bir yün yumağıdır.' FROM texts WHERE slug = 'minik-kedi-pamuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ayşe su kabının temiz olmasına neden dikkat eder?', 'Kap güzel görünsün diye', 'Annesi kızmasın diye', 'Pamuk suyla oynasın diye', 'Hayvanlar da temiz suya ihtiyaç duyduğu için', 'd', 'Metinde hayvanların da bizim gibi temiz suya ihtiyaç duyduğu söyleniyor.' FROM texts WHERE slug = 'minik-kedi-pamuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kediler mutlu olduklarında ne yapar?', 'Tıslar', 'Mırlar', 'Saklanır', 'Havlar', 'b', 'Kediler mutlu olunca mırıl mırıl ses çıkarır, yani mırlar.' FROM texts WHERE slug = 'minik-kedi-pamuk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('bahcedeki-elma-agaci', 'Bahçedeki Elma Ağacı', 'Dedemin bahçesinde büyük bir elma ağacı var. Bu ağacı dedem yıllar önce dikmiş. Şimdi ağaç evden bile daha uzun.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlkbaharda ağacın dalları neyle dolar?', 'Kırmızı elmalarla', 'Beyaz ve pembe çiçeklerle', 'Sarı yapraklarla', 'Karla', 'b', 'İlkbaharda dallar beyaz ve pembe çiçeklerle dolar.' FROM texts WHERE slug = 'bahcedeki-elma-agaci';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yüksek dallardaki elmaları kim toplar?', 'Annem', 'Arılar', 'Ben', 'Dedem', 'd', 'Yüksek dallardaki elmaları dede merdivenle toplar.' FROM texts WHERE slug = 'bahcedeki-elma-agaci';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dede, kışın ağaç için ne söyler?', 'Ağacın uyuduğunu', 'Ağacın hasta olduğunu', 'Ağacın kuruduğunu', 'Ağacın büyüdüğünü', 'a', 'Dede, kışın ağacın uyuduğunu ve baharda uyanacağını söyler.' FROM texts WHERE slug = 'bahcedeki-elma-agaci';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Elma reçeli çok lezzetlidir.', 'Arılar insanları sokar.', 'Elma ağacı her mevsim değişir ve bize çok şey verir.', 'Kışın kar yağar.', 'c', 'Metin, elma ağacının dört mevsimde nasıl değiştiğini anlatıyor.' FROM texts WHERE slug = 'bahcedeki-elma-agaci';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('top-oynamayi-seviyorum', 'Top Oynamayı Seviyorum', 'Benim adım Emre. Ben futbol oynamayı çok seviyorum. Her hafta sonu arkadaşlarımla parkta top oynarız. Park, evimize çok yakın.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Emre maçlarda genellikle hangi görevde oynar?', 'Hakem', 'Forvet', 'Kaleci', 'Seyirci', 'c', 'Emre, genellikle kaleci olduğunu söylüyor.' FROM texts WHERE slug = 'top-oynamayi-seviyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz geçen hafta kaç gol attı?', 'Üç', 'İki', 'Bir', 'Dört', 'a', 'Metinde Deniz''in tam üç gol attığı yazıyor.' FROM texts WHERE slug = 'top-oynamayi-seviyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çocuklar maçtan önce neden ısınır?', 'Daha çok gol atmak için', 'Üşümemek için', 'Hakemi beklemek için', 'Kasları incinmesin diye', 'd', 'Isınma hareketleri sayesinde kaslarının incinmediği söyleniyor.' FROM texts WHERE slug = 'top-oynamayi-seviyorum';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Kaleci olmak kolaydır.', 'Sporun en güzel yanı dostluktur.', 'Her maçı kazanmak gerekir.', 'Park evden uzaktır.', 'b', 'Emre, sporun en güzel yanının dostluk olduğuna inanıyor.' FROM texts WHERE slug = 'top-oynamayi-seviyorum';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('pazar-kahvaltisi', 'Pazar Kahvaltısı', 'Pazar günleri bizim evde çok güzel geçer. Çünkü o gün herkes evdedir. Kimse erkenden işe ya da okula gitmez.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Pazar sabahı evde ilk kim uyanır?', 'Annem', 'Babam', 'Ablam', 'Ben', 'b', 'Metinde sabah ilk uyananın baba olduğu yazıyor.' FROM texts WHERE slug = 'pazar-kahvaltisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Babam ekmeği nereden alır?', 'Marketten', 'Pazardan', 'Komşudan', 'Köşedeki fırından', 'd', 'Baba, köşedeki fırından sıcacık ekmek alır.' FROM texts WHERE slug = 'pazar-kahvaltisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kahvaltıdan sonra masayı kim siler?', 'Ablam', 'Babam', 'Annem', 'Ben', 'a', 'Kahvaltıdan sonra masayı abla siler.' FROM texts WHERE slug = 'pazar-kahvaltisi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Çay en güzel içecektir.', 'Pazar günü okula gidilmez.', 'Ailece birlikte vakit geçirmek güzeldir.', 'Bulaşık yıkamak zordur.', 'c', 'Anlatıcı, pazar kahvaltısını ailesiyle bir arada olduğu için sever.' FROM texts WHERE slug = 'pazar-kahvaltisi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('ayi-taniyalim', 'Ay''ı Tanıyalım', 'Geceleri gökyüzüne baktığımızda en parlak gördüğümüz gök cismi genellikle Ay''dır. Ay, Dünya''nın çevresinde dönen doğal bir uydudur. Dünya''mızın yalnızca bir tane doğal uydusu vardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ay''ın parlak görünmesini sağlayan ışık nereden gelir?', 'Kendi ateşinden', 'Yıldızlardan', 'Güneş''ten', 'Dünya''daki lambalardan', 'c', 'Ay''ın kendi ışığı yoktur, Güneş''ten gelen ışığı yansıtır.' FROM texts WHERE slug = 'ayi-taniyalim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ay''a ayak basan ilk insan kimdir?', 'Neil Armstrong', 'Yuri Gagarin', 'Isaac Newton', 'Galileo', 'a', '1969 yılında Neil Armstrong, Ay''a ayak basan ilk insan oldu.' FROM texts WHERE slug = 'ayi-taniyalim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Astronotların ayak izleri Ay''da neden silinmez?', 'Ay''ın toprağı çok sert olduğu için', 'İzleri koruyan bir cam olduğu için', 'Ay çok soğuk olduğu için', 'İzleri silecek rüzgâr ve yağmur olmadığı için', 'd', 'Ay''da hava olmadığı için rüzgâr esmez, yağmur yağmaz.' FROM texts WHERE slug = 'ayi-taniyalim';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ay''ın şekli neden değişiyormuş gibi görünür?', 'Ay her gece küçülüp büyüdüğü için', 'Aydınlanan kısmını bizden farklı gördüğümüz için', 'Bulutlar Ay''ı kestiği için', 'Ay kendi ışığını açıp kapattığı için', 'b', 'Ay''ın şekli değişmez; değişen, aydınlanan kısmın bizden ne kadar göründüğüdür.' FROM texts WHERE slug = 'ayi-taniyalim';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kayip-harita', 'Kayıp Harita', 'Kerem ile Selin, yaz tatilini köyde, babaannelerinin yanında geçiriyordu. Bir öğleden sonra yağmur yağmaya başladı. Dışarı çıkamayan iki kardeş, evin tavan arasını keşfetmeye karar verdi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kardeşler haritayı nerede buldular?', 'Tavan arasındaki eski bir sandıkta', 'Bahçedeki kuyuda', 'Babaannelerinin çantasında', 'Ceviz ağacının dibinde', 'a', 'Harita, tavan arasındaki eski bir sandığın içindeydi.' FROM texts WHERE slug = 'kayip-harita';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Teneke kutu hangi ağacın dibinden çıktı?', 'Elma ağacının', 'Çınar ağacının', 'Ceviz ağacının', 'Kiraz ağacının', 'c', 'Kardeşler kocaman bir ceviz ağacının dibini kazdılar.' FROM texts WHERE slug = 'kayip-harita';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kutudaki mektubu kim yazmıştı?', 'Selin', 'Köyün muhtarı', 'Kerem''in öğretmeni', 'Babaanneleri', 'd', 'Mektubu elli yıl önce babaanneleri yazmıştı.' FROM texts WHERE slug = 'kayip-harita';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kardeşler neden en büyük hazinenin anılar olduğunu düşündüler?', 'Kutuda altın olmadığı için hayal kırıklığına uğradılar.', 'Kutu, babaannelerinin çocukluğunu ve güzel hatıralarını ortaya çıkardı.', 'Bilyeler çok eskiydi.', 'Harita yanlış çizilmişti.', 'b', 'Kutu sayesinde babaanneleri onlara çocukluğunu anlattı ve bu onları çok mutlu etti.' FROM texts WHERE slug = 'kayip-harita';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('robot-tobi', 'Robot Tobi', 'Bu yıl okulumuzda bir robotik kulübü açıldı. Öğretmenimiz Ahmet Bey, ilk gün masaya küçük, tekerlekli bir robot koydu. Robotun iki yuvarlak gözü ve parlak mavi bir gövdesi vardı. Ona hep birlikte Tobi adını verdik.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahmet Bey''e göre kod nedir?', 'Robotun adı', 'Robotun pili', 'Komutların sırası', 'Tabletin şifresi', 'c', 'Ahmet Bey, komutların sırasına kod dendiğini anlattı.' FROM texts WHERE slug = 'robot-tobi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tobi ilk denemede neden sağa döndü?', 'Çocuklar yanlışlıkla "Sağa dön" bloğunu seçmişti.', 'Tobi''nin pili bitmişti.', 'Sensör bozulmuştu.', 'Kapı kapalıydı.', 'a', 'Kodu incelediklerinde yanlış bloğu seçtiklerini fark ettiler.' FROM texts WHERE slug = 'robot-tobi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Tobi''nin sensörü ne işe yarar?', 'Müzik çalar', 'Işık yakar', 'Konuşmasını sağlar', 'Önündeki engelleri algılar', 'd', 'Sensör, önüne engel çıkınca Tobi''nin durmasını sağlıyordu.' FROM texts WHERE slug = 'robot-tobi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ahmet Bey hata yapmak hakkında ne düşünüyor?', 'Hata yapmak utanç vericidir.', 'Hata yapmak öğrenmenin bir parçasıdır.', 'Mühendisler hiç hata yapmaz.', 'Hata yapan tekrar denememelidir.', 'b', 'Ahmet Bey, hata yapmanın öğrenmenin bir parçası olduğunu söyledi.' FROM texts WHERE slug = 'robot-tobi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kumsalda-kesif', 'Kumsalda Bir Keşif', 'Deniz, cumartesi sabahı babasıyla birlikte kumsala gitti. Yanına bir kova, bir büyüteç ve küçük bir defter aldı. Bugün bir kâşif gibi kumsalı inceleyecekti.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz kumsala giderken yanına neler aldı?', 'Top, havlu ve şapka', 'Kova, büyüteç ve defter', 'Olta, kova ve kürek', 'Kitap, kalem ve dürbün', 'b', 'Deniz yanına bir kova, bir büyüteç ve küçük bir defter aldı.' FROM texts WHERE slug = 'kumsalda-kesif';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yengeç nasıl yürüyordu?', 'Öne doğru', 'Geriye doğru', 'Zıplayarak', 'Yana doğru', 'd', 'Metinde yengecin öne değil yana doğru yürüdüğü yazıyor.' FROM texts WHERE slug = 'kumsalda-kesif';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Deniz kumsalda çöp görünce neden üzüldü?', 'Çöpler denizdeki canlılara zarar verebileceği için', 'Kumsal çirkin göründüğü için', 'Oyun oynayacak yer kalmadığı için', 'Babası kızdığı için', 'a', 'Deniz, çöplerin deniz canlılarına zarar verebileceğini biliyordu.' FROM texts WHERE slug = 'kumsalda-kesif';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Yengeçler tehlikeli hayvanlardır.', 'Deniz kabukları toplamak eğlencelidir.', 'Kumsal birçok canlının evidir ve temiz tutulmalıdır.', 'Yosunlar kaygandır.', 'c', 'Deniz''in son notu metnin ana fikrini özetliyor.' FROM texts WHERE slug = 'kumsalda-kesif';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('karincalarin-gizli-dunyasi', 'Karıncaların Gizli Dünyası', 'Bahçede yürürken yerde uzun bir çizgi hâlinde ilerleyen karıncaları hiç fark ettiniz mi? Bu minik canlılar, göründüklerinden çok daha düzenli ve çalışkan bir hayat sürer.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kraliçe karıncanın görevi nedir?', 'Yiyecek aramak', 'Yumurta bırakmak', 'Yuvayı korumak', 'Tünel kazmak', 'b', 'Metinde kraliçe karıncanın görevinin yumurta bırakmak olduğu yazıyor.' FROM texts WHERE slug = 'karincalarin-gizli-dunyasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karıncalar neden tek sıra hâlinde aynı yoldan yürür?', 'Kraliçe onlara yolu gösterdiği için', 'Gözleri çok iyi gördüğü için', 'Yere bırakılan özel kokuyu takip ettikleri için', 'Yol en kısa olduğu için', 'c', 'Yiyecek bulan karınca yere koku bırakır, diğerleri bu kokuyu izler.' FROM texts WHERE slug = 'karincalarin-gizli-dunyasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Karınca yuvasında neler bulunur?', 'Birbirine bağlı tüneller ve odalar', 'Yalnızca tek bir büyük oda', 'Yapraklardan yapılmış duvarlar', 'Su dolu havuzlar', 'a', 'Toprağın altında birbirine bağlanan tüneller ve odalar bulunur.' FROM texts WHERE slug = 'karincalarin-gizli-dunyasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Karıncalar insanlara zarar verir.', 'Karıncalar yalnız yaşamayı sever.', 'Karıncalar yalnızca yaz aylarında çalışır.', 'Karıncalar iş birliği içinde, düzenli bir hayat sürer.', 'd', 'Metin, karıncaların görev paylaşımını ve düzenli yaşamını anlatıyor.' FROM texts WHERE slug = 'karincalarin-gizli-dunyasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('suyun-yolculugu', 'Suyun Yolculuğu', 'Bugün içtiğiniz bir bardak su, belki de milyonlarca yıl önce bir dinozorun içtiği suyun ta kendisi. Kulağa şaşırtıcı gelse de bu mümkün. Çünkü Dünya''daki su hiç kaybolmaz, yalnızca durmadan yolculuk eder. Bu yolculuğa su döngüsü denir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Su buharının soğuyarak minicik su damlacıklarına dönüşmesine ne denir?', 'Buharlaşma', 'Yağış', 'Yoğuşma', 'Donma', 'c', 'Metinde bu olaya yoğuşma dendiği açıklanıyor.' FROM texts WHERE slug = 'suyun-yolculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Suyun yolculuğu neyle başlar?', 'Güneş''in suyu ısıtmasıyla', 'Kar yağmasıyla', 'Rüzgârın esmesiyle', 'Bitkilerin su içmesiyle', 'a', 'Yolculuk, Güneş''in denizleri, gölleri ve nehirleri ısıtmasıyla başlar.' FROM texts WHERE slug = 'suyun-yolculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hava çok soğuksa yağış nasıl iner?', 'Sis olarak', 'Buhar olarak', 'Yalnızca yağmur olarak', 'Kar ya da dolu olarak', 'd', 'Hava çok soğukken yağış kar ya da dolu olarak iner.' FROM texts WHERE slug = 'suyun-yolculugu';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre suyu neden dikkatli kullanmalıyız?', 'Su döngüsü durduğu için', 'İçebileceğimiz temiz su az olduğu için', 'Su çok pahalı olduğu için', 'Denizler kuruduğu için', 'b', 'Dünya''daki suyun çoğu tuzludur, içilebilir temiz su azdır.' FROM texts WHERE slug = 'suyun-yolculugu';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('catalhoyuk', 'Çatalhöyük: Kapısı Çatıda Olan Evler', 'Konya Ovası''nda, bugünkü Çumra ilçesinin yakınında çok eski bir yerleşim yeri bulunur. Adı Çatalhöyük''tür. Bilim insanlarına göre burada yaklaşık dokuz bin yıl önce insanlar yaşıyordu. Bu da Çatalhöyük''ü dünyanın bilinen en eski yerleşim yerlerinden biri yapar.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çatalhöyük''te insanlar evlerine nasıl girerdi?', 'Ön kapıdan', 'Çatıdaki açıklıktan merdivenle', 'Pencereden atlayarak', 'Yer altındaki tünellerden', 'b', 'Her evin çatısında bir açıklık vardı ve insanlar merdivenle aşağı inerdi.' FROM texts WHERE slug = 'catalhoyuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çatalhöyük''ün evleri neyle yapılmıştı?', 'Taş ve mermerle', 'Ahşap ve camla', 'Demir ve betonla', 'Kerpiçle', 'd', 'Evler, çamur ve samandan yapılan kerpiç tuğlalarla inşa edilmişti.' FROM texts WHERE slug = 'catalhoyuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çatalhöyük halkı neden sürekli yer değiştirmek zorunda kalmadı?', 'Tarım yapıp hayvan besledikleri için', 'Evleri çok büyük olduğu için', 'Başka yerler çok soğuk olduğu için', 'Yürümeyi sevmedikleri için', 'a', 'Buğday ve arpa yetiştirip koyun ve keçi besledikleri için yiyecekleri yanlarındaydı.' FROM texts WHERE slug = 'catalhoyuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Çatalhöyük hangi ilimizdedir?', 'İzmir', 'Ankara', 'Konya', 'Trabzon', 'c', 'Çatalhöyük, Konya Ovası''nda, Çumra ilçesi yakınındadır.' FROM texts WHERE slug = 'catalhoyuk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('maratonun-hikayesi', 'Maratonun Hikâyesi', 'Maraton, 42 kilometre 195 metre uzunluğunda bir koşu yarışıdır. Bugün dünyanın pek çok şehrinde maratonlar düzenlenir. İstanbul Maratonu ise koşucuların Asya''dan Avrupa''ya geçtiği, kıtalar arasında koşulan ender yarışlardan biridir. Peki bu yarışın adı nereden geliyor?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Maraton yarışı adını nereden alır?', 'Ünlü bir koşucudan', 'Bir Yunan tanrısından', 'Yunanistan''daki bir ovadan', 'İstanbul''daki bir semtten', 'c', 'Maraton, adını Yunanistan''daki Maraton Ovası''ndan alır.' FROM texts WHERE slug = 'maratonun-hikayesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İlk modern Olimpiyat Oyunları ne zaman ve nerede yapıldı?', '1896''da Atina''da', '1908''de Londra''da', '1900''de Paris''te', '1896''da İstanbul''da', 'a', 'İlk modern Olimpiyat Oyunları 1896 yılında Atina''da düzenlendi.' FROM texts WHERE slug = 'maratonun-hikayesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metinde Filipides''in hikâyesi için ne söyleniyor?', 'Kesin olarak yaşanmış bir olaydır.', 'Kesin olarak yaşandığı bilinmeyen bir efsanedir.', 'Bir çizgi filmden alınmıştır.', '1908 yılında yaşanmıştır.', 'b', 'Tarihçiler hikâyenin böyle yaşanıp yaşanmadığından emin değildir; bu bir efsanedir.' FROM texts WHERE slug = 'maratonun-hikayesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre birçok maraton koşucusunun asıl amacı nedir?', 'Para ödülü kazanmak', 'Herkesi geçmek', 'Madalya toplamak', 'Kendi sınırlarını zorlamak ve yarışı bitirmek', 'd', 'Birçok koşucu için asıl amaç kendi sınırlarını zorlamak ve yarışı bitirmektir.' FROM texts WHERE slug = 'maratonun-hikayesi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('fenerdeki-firtinali-gece', 'Fenerdeki Fırtınalı Gece', 'Ege kıyısındaki küçük bir adada, yaşlı bir deniz feneri vardı. Fenerin bekçisi Hasan Dede''ydi. On yaşındaki torunu Mert, o yaz dedesinin yanında kalıyordu. Mert her akşam dedesiyle birlikte fenerin döner merdivenlerini tırmanır, büyük lambanın yanmasını izlerdi.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hasan Dede''ye göre fener gemiler için neden önemlidir?', 'Kaptanlara tehlikeli kayalıkları gösterdiği için', 'Gemilere yakıt verdiği için', 'Balıkları kıyıya çektiği için', 'Saatin kaç olduğunu gösterdiği için', 'a', 'Fenerin ışığı kaptanlara nereden uzak durmaları gerektiğini gösterir.' FROM texts WHERE slug = 'fenerdeki-firtinali-gece';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Fenerin lambası neden söndü?', 'Ampul patladığı için', 'Hasan Dede lambayı kapattığı için', 'Elektrikler kesildiği için', 'Lambaya su girdiği için', 'c', 'Fırtına sırasında elektrikler kesildi ve lamba söndü.' FROM texts WHERE slug = 'fenerdeki-firtinali-gece';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert dedesine nasıl yardım etti?', 'Balıkçıya telefon etti', 'El feneriyle yolu aydınlattı ve aletleri uzattı', 'Tekneye yüzerek gitti', 'Lambayı tamir etti', 'b', 'Mert, el feneriyle dedesinin önünü aydınlattı ve ona aletleri uzattı.' FROM texts WHERE slug = 'fenerdeki-firtinali-gece';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mert bu olaydan ne öğrendi?', 'Fırtınaların hiç tehlikeli olmadığını', 'Balık tutmanın kolay olduğunu', 'Jeneratörün nasıl yapıldığını', 'Cesaretin, korksa da doğru olanı yapmak olduğunu', 'd', 'Metnin sonunda Mert''in cesaretle ilgili öğrendiği açıkça yazıyor.' FROM texts WHERE slug = 'fenerdeki-firtinali-gece';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yapraklar-neden-sararir', 'Yapraklar Neden Sararır?', 'Sonbaharda parklarda yürürken ayaklarımızın altında hışırdayan sarı, turuncu ve kırmızı yapraklar görürüz. Oysa yazın aynı ağaçlar yemyeşildi. Peki yapraklar neden renk değiştirir?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yapraklara yeşil rengini veren madde hangisidir?', 'Oksijen', 'Klorofil', 'Karbondioksit', 'Su', 'b', 'Yapraklarda bulunan klorofil yeşil renklidir.' FROM texts WHERE slug = 'yapraklar-neden-sararir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Ağaçlar sonbaharda neden klorofil üretmeyi bırakır?', 'Yapraklar yaşlandığı için', 'Yağmur çok yağdığı için', 'Kuşlar yaprakları yediği için', 'Günler kısalıp daha az Güneş ışığı aldıkları için', 'd', 'Sonbaharda günler kısalır ve ağaçlar eskisi kadar Güneş ışığı alamaz.' FROM texts WHERE slug = 'yapraklar-neden-sararir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Dökülen yapraklara ne olur?', 'Çürüyerek toprağı besler', 'Rüzgârla uzaya uçar', 'Yeniden dallara yapışır', 'Taşa dönüşür', 'a', 'Dökülen yapraklar toprağın üzerinde çürüyerek toprağı besler.' FROM texts WHERE slug = 'yapraklar-neden-sararir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yapraklardaki sarı ve turuncu renkler yazın neden görünmez?', 'Yazın bu renkler hiç yoktur.', 'Güneş bu renkleri soldurur.', 'Klorofilin güçlü yeşil rengi onları gizler.', 'Yapraklar yazın çok küçüktür.', 'c', 'Sarı ve turuncu maddeler yazın da vardır ama yeşil klorofil onları gizler.' FROM texts WHERE slug = 'yapraklar-neden-sararir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('gunes-sisteminde-yolculuk', 'Güneş Sistemi''nde Bir Yolculuk', 'Hayal gücümüzü kullanarak bir uzay gemisine bindiğimizi düşünelim. Yolculuğumuz Güneş Sistemi''nin merkezinden, yani Güneş''ten başlıyor. Güneş aslında bir yıldızdır. Bize diğer yıldızlardan çok daha büyük ve parlak görünmesinin nedeni, Dünya''ya çok daha yakın olmasıdır. Güneş''in içine yaklaşık bir milyon Dünya sığabilir. Işığı ve ısısı olmasaydı gezegenimizde yaşam mümkün olmazdı.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş Sistemi''nin en sıcak gezegeni hangisidir?', 'Merkür', 'Mars', 'Venüs', 'Jüpiter', 'c', 'Metinde Venüs''ün en sıcak gezegen olduğu yazıyor.' FROM texts WHERE slug = 'gunes-sisteminde-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Venüs, Güneş''e daha yakın olan Merkür''den neden daha sıcaktır?', 'Kalın atmosferi ısıyı hapsettiği için', 'Daha büyük olduğu için', 'Üzerinde yanardağlar olduğu için', 'Daha yavaş döndüğü için', 'a', 'Venüs''ün kalın atmosferi ısıyı bir battaniye gibi hapseder.' FROM texts WHERE slug = 'gunes-sisteminde-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Mars neden kırmızı görünür?', 'Çok sıcak olduğu için', 'Toprağındaki paslı demir tozları nedeniyle', 'Üzerinde kırmızı bitkiler olduğu için', 'Güneş''e en yakın gezegen olduğu için', 'b', 'Mars''ın toprağındaki paslı demir tozları ona kırmızı rengini verir.' FROM texts WHERE slug = 'gunes-sisteminde-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş''ten çıkan ışık Dünya''ya yaklaşık kaç dakikada ulaşır?', 'Bir dakikada', 'Otuz dakikada', 'Altmış dakikada', 'Sekiz dakikada', 'd', 'Işık çok hızlı olmasına rağmen Dünya''ya ancak sekiz dakikada ulaşır.' FROM texts WHERE slug = 'gunes-sisteminde-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş, bize diğer yıldızlardan neden daha büyük ve parlak görünür?', 'Evrenin en büyük yıldızı olduğu için', 'Gezegen olduğu için', 'Dünya''ya çok daha yakın olduğu için', 'Yalnızca gündüz parladığı için', 'c', 'Güneş de bir yıldızdır; bize çok daha yakın olduğu için büyük ve parlak görünür.' FROM texts WHERE slug = 'gunes-sisteminde-yolculuk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('piri-reis-haritasi', 'Piri Reis ve Ünlü Haritası', 'Günümüzde bir yere gitmek istediğimizde telefonumuzdaki haritaya bakmamız yeterli. Uydular sayesinde dünyanın her köşesini görebiliyoruz. Peki uyduların, uçakların, hatta fotoğraf makinelerinin bile olmadığı zamanlarda haritalar nasıl çiziliyordu? Bu sorunun en ünlü cevaplarından biri, Osmanlı denizcisi Piri Reis''tir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Piri Reis''in 1513 yılındaki haritası neyin üzerine çizilmişti?', 'Kâğıdın', 'Ceylan derisinin', 'Tahta bir levhanın', 'İpek kumaşın', 'b', 'Harita, ceylan derisi üzerine renkli mürekkeplerle çizilmişti.' FROM texts WHERE slug = 'piri-reis-haritasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kitab-ı Bahriye nasıl bir eserdir?', 'Bir masal kitabı', 'Bir yemek kitabı', 'Bir şiir kitabı', 'Denizciler için hazırlanmış bir rehber', 'd', 'Kitab-ı Bahriye; limanlar, rüzgârlar ve tehlikeli yerler hakkında bilgi veren bir denizcilik rehberidir.' FROM texts WHERE slug = 'piri-reis-haritasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Haritanın günümüze ulaşan parçası nerede bulundu?', 'Topkapı Sarayı''nda', 'Gelibolu''da bir evde', 'Bir gemi enkazında', 'Yurt dışındaki bir müzede', 'a', 'Harita parçası 1929 yılında Topkapı Sarayı''nda bulundu.' FROM texts WHERE slug = 'piri-reis-haritasi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Piri Reis''in çalışma yöntemi hakkında hangisi söylenebilir?', 'Hiçbir kaynağa bakmadan çizmiştir.', 'Haritayı uydu fotoğraflarından çizmiştir.', 'Farklı kaynakları karşılaştırarak titizlikle çalışmıştır.', 'Haritayı yalnızca hayal gücüyle çizmiştir.', 'c', 'Piri Reis, yirmi kadar eski haritadan yararlanıp bilgileri karşılaştırmıştır.' FROM texts WHERE slug = 'piri-reis-haritasi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('internet-nasil-calisir', 'İnternet Nasıl Çalışır?', 'Bir videoyu izlemek, bir oyunu oynamak ya da uzaktaki bir akrabamızla görüntülü konuşmak için internete bağlanırız. Birkaç saniye içinde başka bir şehirden, hatta başka bir kıtadan bilgiler ekranımıza gelir. Peki bu bilgiler bize nasıl ulaşıyor?
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İnternette bir bilgi gönderilmeden önce ne olur?', 'Paket adı verilen küçük parçalara bölünür', 'Kâğıda yazdırılır', 'Bir kutuya konur', 'Renkli ışıklara boyanır', 'a', 'Her bilgi yola çıkmadan önce paket adı verilen küçük parçalara bölünür.' FROM texts WHERE slug = 'internet-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Okyanusların dibinde kıtaları birbirine bağlayan nedir?', 'Tüneller', 'Uydular', 'Fiber optik kablolar', 'Denizaltılar', 'c', 'Okyanus diplerinde binlerce kilometrelik fiber optik kablolar vardır.' FROM texts WHERE slug = 'internet-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre sunucu nedir?', 'İnternet faturası', 'Bir oyun türü', 'Evdeki modem', 'Videoların ve sitelerin saklandığı güçlü bilgisayar', 'd', 'Videolar ve siteler, sunucu adı verilen güçlü bilgisayarlarda saklanır.' FROM texts WHERE slug = 'internet-nasil-calisir';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'İnterneti güvenli kullanmak için ne yapmalıyız?', 'Şifremizi arkadaşlarımıza söylemeliyiz.', 'Kişisel bilgilerimizi tanımadığımız kişilerle paylaşmamalıyız.', 'Her gördüğümüz bağlantıya tıklamalıyız.', 'Sorunları kimseye anlatmamalıyız.', 'b', 'Metinde kişisel bilgileri tanımadığımız kişilerle paylaşmamamız gerektiği söyleniyor.' FROM texts WHERE slug = 'internet-nasil-calisir';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('kutuplara-yolculuk', 'Kutuplara Yolculuk', 'Dünya''mızın en soğuk ve en ıssız yerleri, kutup bölgeleridir. Gezegenimizin en kuzeyinde Kuzey Kutbu, en güneyinde ise Güney Kutbu bulunur. Bu iki bölge birbirine benzese de aralarında önemli farklar vardır.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kuzey Kutbu nerede bulunur?', 'Bir kıtanın ortasında', 'Donmuş bir okyanusun ortasında', 'Yüksek bir dağın tepesinde', 'Bir adanın üzerinde', 'b', 'Kuzey Kutbu, donmuş Arktik Okyanusu''nun ortasındadır.' FROM texts WHERE slug = 'kutuplara-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kutup ayıları ile penguenler doğada neden hiç karşılaşmaz?', 'Penguenler kutup ayılarından saklandığı için', 'İkisi de kış uykusuna yattığı için', 'Kutup ayıları yüzemediği için', 'Biri kuzeyde, diğeri güneyde yaşadığı için', 'd', 'Kutup ayıları kuzeyde, penguenler ise güneyde yaşar.' FROM texts WHERE slug = 'kutuplara-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Kutuplarda yaz aylarında ne olur?', 'Güneş hiç batmaz', 'Güneş hiç doğmaz', 'Bütün buzlar erir', 'Her gün yağmur yağar', 'a', 'Dünya''nın ekseni eğik olduğu için kutuplarda yazın Güneş hiç batmaz.' FROM texts WHERE slug = 'kutuplara-yolculuk';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bilim insanları buzun içindeki eski hava kabarcıklarını neden inceler?', 'İçme suyu elde etmek için', 'Penguenleri saymak için', 'Binlerce yıl önceki iklimi öğrenmek için', 'Yeni buz yapmak için', 'c', 'Bu kabarcıklar, geçmişteki iklim hakkında bilgi verir.' FROM texts WHERE slug = 'kutuplara-yolculuk';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('isik-ve-renkler', 'Işık ve Renkler', 'Güneşli bir günde yağmur yağarken gökyüzünde beliren gökkuşağını izlemek, doğanın sunduğu en güzel manzaralardan biridir. Kırmızıdan mora uzanan bu renk şeridi, ışığın bize anlattığı büyüleyici bir hikâyenin parçasıdır. Bu hikâyeyi anlamak için önce ışığın ne olduğunu düşünmemiz gerekir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Beyaz ışığın renklere ayrılabildiğini prizma deneyiyle gösteren bilim insanı kimdir?', 'Galileo Galilei', 'Albert Einstein', 'Isaac Newton', 'Marie Curie', 'c', 'Newton, prizma deneyiyle beyaz ışığın renklere ayrılabildiğini gösterdi.' FROM texts WHERE slug = 'isik-ve-renkler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre prizma nedir?', 'Üçgen biçimli bir cam parçası', 'Bir çeşit mercek gözlük', 'Işık üreten bir lamba', 'Renkli bir boya', 'a', 'Metinde prizmanın üçgen biçimli bir cam parçası olduğu açıklanıyor.' FROM texts WHERE slug = 'isik-ve-renkler';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Gökkuşağını görebilmek için Güneş ve yağmur nerede olmalıdır?', 'İkisi de önümüzde olmalıdır.', 'Güneş önümüzde, yağmur arkamızda olmalıdır.', 'İkisi de arkamızda olmalıdır.', 'Güneş arkamızda, yağmur önümüzde olmalıdır.', 'd', 'Metinde Güneş''in arkamızda, yağmurun önümüzde olması gerektiği yazıyor.' FROM texts WHERE slug = 'isik-ve-renkler';
