INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('hezarfen-efsanesi', 'Hezarfen Ahmed Çelebi Efsanesi', 'İnsanlar binlerce yıl boyunca gökyüzünde süzülen kuşları hayranlıkla izlemiş ve bir gün onlar gibi uçabilmeyi hayal etmiştir. Bu hayali gerçekleştirmeye çalıştığı anlatılanlar arasında, ülkemizde en çok bilinen isimlerden biri Hezarfen Ahmed Çelebi''dir.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, '"Hezarfen" kelimesi ne anlama gelir?', 'Kuş gibi uçan', 'Bin fenli, yani pek çok bilgiye ve beceriye sahip', 'Cesur savaşçı', 'Kule bekçisi', 'b', 'Metinde Hezarfen kelimesinin "bin fenli" anlamına geldiği açıklanıyor.' FROM texts WHERE slug = 'hezarfen-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hezarfen hakkındaki bilgilerin neredeyse tamamı hangi kaynaktan gelir?', 'Piri Reis''in Kitab-ı Bahriye''sinden', 'Padişahın mektuplarından', 'Gazete haberlerinden', 'Evliya Çelebi''nin Seyahatname''sinden', 'd', 'Bilgilerimizin neredeyse tamamı Evliya Çelebi''nin Seyahatname adlı eserinden gelir.' FROM texts WHERE slug = 'hezarfen-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Anlatılana göre Hezarfen nereye inmiştir?', 'Üsküdar''daki Doğancılar Meydanı''na', 'Okmeydanı''na', 'Galata Kulesi''nin bahçesine', 'Cezayir''e', 'a', 'Evliya Çelebi''ye göre Hezarfen, Üsküdar''daki Doğancılar Meydanı''na inmiştir.' FROM texts WHERE slug = 'hezarfen-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Hezarfen''in uçuşu neden bir efsane olarak kabul edilir?', 'Hezarfen hiç yaşamadığı için', 'Uçuş bir masal kitabında anlatıldığı için', 'Olayı doğrulayan başka bir kaynak olmadığı ve mesafe çok uzun olduğu için', 'Wright kardeşler bunu yalanladığı için', 'c', 'Mesafe üç kilometreden fazladır ve olayı doğrulayan başka bir kaynak yoktur.' FROM texts WHERE slug = 'hezarfen-efsanesi';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metnin ana fikri nedir?', 'Galata Kulesi çok yüksektir.', 'Padişahlar mucitleri hep ödüllendirmiştir.', 'Uçmak çok tehlikeli bir iştir.', 'Büyük buluşlar merak eden ve cesurca deneyen insanların hayalleriyle başlar.', 'd', 'Metnin son bölümü, efsanenin anlattığı bu önemli düşünceyi vurguluyor.' FROM texts WHERE slug = 'hezarfen-efsanesi';
INSERT INTO texts (slug, title, content, category, difficulty, grade_level, word_count, estimated_duration, source_type, is_placement) VALUES ('yildizlarin-yasami', 'Yıldızların Yaşamı', 'Açık bir gecede şehir ışıklarından uzak bir yerde gökyüzüne bakarsak binlerce yıldız görebiliriz. Bu yıldızlar gökyüzünde hep aynı yerde duruyormuş gibi görünür. Oysa her yıldızın, tıpkı canlılar gibi, bir doğuşu, uzun bir yaşamı ve bir sonu vardır. Yalnız bir yıldızın yaşamı milyonlarca, hatta milyarlarca yıl sürer.
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Yıldızlar nerede doğar?', 'Bulutsu adı verilen dev gaz ve toz bulutlarında', 'Gezegenlerin içinde', 'Kara deliklerin merkezinde', 'Ay''ın yüzeyinde', 'a', 'Yıldızlar, bulutsu adı verilen dev gaz ve toz bulutlarının içinde doğar.' FROM texts WHERE slug = 'yildizlarin-yasami';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş yaklaşık kaç yaşındadır?', 'Beş bin yaşında', 'Bir milyon yaşında', '4,6 milyar yaşında', 'Yüz milyar yaşında', 'c', 'Metinde Güneş''in yaklaşık 4,6 milyar yaşında olduğu yazıyor.' FROM texts WHERE slug = 'yildizlarin-yasami';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Güneş''ten çok daha büyük kütleli yıldızlar yaşamlarını nasıl bitirir?', 'Yavaşça soğuyarak', 'Gezegene dönüşerek', 'Buz tutarak', 'Süpernova adı verilen dev bir patlamayla', 'd', 'Büyük kütleli yıldızlar yaşamlarını süpernova patlamasıyla bitirir.' FROM texts WHERE slug = 'yildizlarin-yasami';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Bazı bilim insanları neden hepimizin yıldız tozundan yapıldığını söyler?', 'Geceleri yıldızlara baktığımız için', 'Vücudumuzdaki bazı elementler yıldızların içinde oluştuğu için', 'Uzaydan toz yağdığı için', 'Güneş bizi ısıttığı için', 'b', 'Karbon, oksijen ve demir gibi elementler yıldızların içinde oluşmuştur.' FROM texts WHERE slug = 'yildizlarin-yasami';
INSERT INTO questions (text_id, question, option_a, option_b, option_c, option_d, correct_option, explanation) SELECT id, 'Metne göre Güneş''in yaşamının sonunda geriye ne kalacaktır?', 'Bir kara delik', 'Bir nötron yıldızı', 'Bir beyaz cüce', 'Yeni bir gezegen', 'c', 'Güneş dış katmanlarını savurduktan sonra geriye bir beyaz cüce kalacaktır.' FROM texts WHERE slug = 'yildizlarin-yasami';
